-- FIND_ACTIVE_TABLES.sql  - run as SALES_NEW. Reads SCLKHI/SCLISB only; writes only to helper table CHK_ACTIVE in SALES_NEW.
-- Does not use the data dictionary (it is damaged on this server).
SET DEFINE OFF
SET FEEDBACK OFF
SET TIMING OFF
WHENEVER SQLERROR CONTINUE
CREATE TABLE CHK_ACTIVE (db VARCHAR2(3), tbl VARCHAR2(30), n_rows NUMBER, last_dt DATE);
DELETE FROM CHK_ACTIVE;
COMMIT;
SET FEEDBACK ON
SET PAGESIZE 500 LINESIZE 120
COLUMN tbl FORMAT A30
ALTER SESSION SET NLS_DATE_FORMAT = 'DD-MM-YYYY';
PROMPT ===== tables with data on/after 01-09-2026 =====
SELECT db, tbl, n_rows, last_dt FROM CHK_ACTIVE WHERE last_dt >= DATE '2026-09-01' ORDER BY db, last_dt DESC, tbl;
PROMPT ===== (afterwards you can run: DROP TABLE CHK_ACTIVE PURGE;) =====
